<?php $this->assign('title', $venda->numero); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3"><?= h($venda->numero) ?></h1><span class="badge text-bg-secondary"><?= h($venda->status) ?></span></div><?php if ($venda->status === 'finalizada'): ?><?= $this->Form->postLink('Cancelar venda', ['action' => 'cancelar', $venda->id], ['data' => ['motivo' => 'Cancelamento operacional'], 'class' => 'btn btn-outline-danger', 'confirm' => 'Cancelar e estornar?']) ?><?php endif; ?></div><div class="card border-0 shadow-sm mb-3"><table class="table mb-0"><thead><tr><th>Item</th><th>Lote</th><th>Quantidade</th><th>Total</th></tr></thead><tbody><?php foreach ($venda->vendas_itens as $item): ?><tr><td><?= h($item->medicamento?->nome_comercial ?? $item->produto?->nome ?? '-') ?></td><td><?= h($item->lote?->numero_lote ?? '-') ?></td><td><?= h($item->quantidade) ?></td><td><?= h($item->total) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="3">Total</th><th>R$ <?= number_format((float)$venda->total, 2, ',', '.') ?></th></tr></tfoot></table></div><?php foreach ($venda->pagamentos as $pagamento): ?><div class="alert alert-secondary"><?= h(strtoupper($pagamento->forma)) ?> · R$ <?= number_format((float)$pagamento->valor, 2, ',', '.') ?> · <?= h($pagamento->status) ?></div><?php endforeach; ?>
